-- Migration: Add validation constraints to prevent data quality issues

-- 1. Add CHECK constraint for difficulty_level (must be uppercase)
ALTER TABLE questions
ADD CONSTRAINT check_difficulty_level_uppercase
CHECK (difficulty_level IN ('EASY', 'MEDIUM', 'HARD') OR difficulty_level IS NULL);

-- 2. Create function to validate question completeness before insert/update
CREATE OR REPLACE FUNCTION validate_question_for_mock()
RETURNS TRIGGER AS $$
BEGIN
  -- Ensure exam_tag is set for TNPSC questions
  IF NEW.exam_tag LIKE 'TNPSC_%' THEN
    
    -- unit_code should not be NULL (auto-generated by existing trigger)
    IF NEW.unit_code IS NULL AND NEW.unit_name IS NOT NULL THEN
      -- Let the existing trigger handle this
      NULL;
    END IF;
    
    -- correct_option must be set (A, B, C, D, or E)
    IF NEW.correct_option IS NULL THEN
      RAISE NOTICE 'Question % has NULL correct_option - will be excluded from mock tests', NEW.id;
    END IF;
    
    -- Standardize difficulty_level to uppercase if provided
    IF NEW.difficulty_level IS NOT NULL THEN
      NEW.difficulty_level := UPPER(NEW.difficulty_level);
    END IF;
    
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 3. Create trigger to validate on insert/update
DROP TRIGGER IF EXISTS trigger_validate_question_for_mock ON questions;
CREATE TRIGGER trigger_validate_question_for_mock
BEFORE INSERT OR UPDATE ON questions
FOR EACH ROW
EXECUTE FUNCTION validate_question_for_mock();

-- 4. Create view to check question bank health
CREATE OR REPLACE VIEW question_bank_health AS
WITH blueprint AS (
  SELECT 'TNPSC_GROUP_1' as exam_tag UNION ALL
  SELECT 'TNPSC_GROUP_2' UNION ALL
  SELECT 'TNPSC_GROUP_4'
),
unit_counts AS (
  SELECT 
    q.exam_tag,
    q.unit_code,
    q.difficulty_level,
    COUNT(q.id) as question_count
  FROM questions q
  INNER JOIN papers p ON q.paper_id = p.id
  WHERE q.exam_tag IN ('TNPSC_GROUP_1', 'TNPSC_GROUP_2', 'TNPSC_GROUP_4')
    AND p.exam_type NOT IN ('Full Mock', 'Custom')
    AND q.correct_option IS NOT NULL
    AND q.unit_code IS NOT NULL
  GROUP BY q.exam_tag, q.unit_code, q.difficulty_level
)
SELECT 
  b.exam_tag,
  COUNT(DISTINCT uc.unit_code) as units_with_questions,
  SUM(CASE WHEN uc.difficulty_level = 'EASY' THEN uc.question_count ELSE 0 END) as total_easy,
  SUM(CASE WHEN uc.difficulty_level = 'MEDIUM' THEN uc.question_count ELSE 0 END) as total_medium,
  SUM(CASE WHEN uc.difficulty_level = 'HARD' THEN uc.question_count ELSE 0 END) as total_hard,
  SUM(uc.question_count) as total_questions
FROM blueprint b
LEFT JOIN unit_counts uc ON b.exam_tag = uc.exam_tag
GROUP BY b.exam_tag
ORDER BY b.exam_tag;

-- 5. Comment
COMMENT ON VIEW question_bank_health IS 'Shows question bank health metrics for each exam group to identify gaps before mock test generation';
